func newWorkflowArchiveCmd(flags *rootFlags) *cobra.Command {
	var dbPath string
	var full bool

	cmd := &cobra.Command{
		Use:   "archive",
		Short: "Sync all resources to local store for offline access and search",
		Long: `Archive fetches all syncable resources from the API and stores them in a
local SQLite database. Supports incremental sync (only new data since last run)
and full resync. After archiving, use 'search' for instant full-text search.`,
		Example: `  # Archive all resources
  judgeme-pp-cli workflow archive

  # Full re-archive (ignore previous sync state)
  judgeme-pp-cli workflow archive --full`,
		RunE: func(cmd *cobra.Command, args []string) error {
			c, err := flags.newClient()
			if err != nil {
				return err
			}
			c.NoCache = true

			if dbPath == "" {
				dbPath = defaultDBPath("judgeme-pp-cli")
			}
			s, err := store.OpenWithContext(cmd.Context(), dbPath)
			if err != nil {
				return fmt.Errorf("opening store: %w", err)
			}
			defer s.Close()

			resources := []string{"webhooks", "widgets", "widgets-all-reviews-count", "widgets-all-reviews-page", "widgets-all-reviews-rating", "widgets-product-review"}
			totalSynced := 0
			resourceCount := len(resources)
			syncEventWriter := cmd.OutOrStdout()
			if flags.asJSON {
				syncEventWriter = cmd.ErrOrStderr()
			}

			if !cliutil.IsDogfoodEnv() {
				corpus, err := fetchJudgeMeCorpus(cmd.Context(), c)
				if err != nil {
					return classifyAPIError(err, flags)
				}
				livePublished, err := judgeMeReviewCount(cmd.Context(), c, map[string]string{"published": "true"})
				if err != nil {
					return classifyAPIError(err, flags)
				}
				if corpus.Published != livePublished {
					return fmt.Errorf("published population mismatch during archive: local=%d live_count=%d; refusing success", corpus.Published, livePublished)
				}
				if err := replaceJudgeMeReviewCorpus(cmd.Context(), s.DB(), corpus); err != nil {
					return fmt.Errorf("committing verified review corpus: %w", err)
				}
				totalSynced += len(corpus.Reviews)
				resourceCount++
				fmt.Fprintf(cmd.ErrOrStderr(), "  reviews: %d count-verified rows synced\n", len(corpus.Reviews))
			}

			// --full clears the cursor here because syncResource reads
			// existingCursor unconditionally; its full param only gates the
			// since filter, not cursor reset. Mirrors newSyncCmd's pattern.
			if full {
				for _, resource := range resources {
					_ = s.SaveSyncState(resource, "", 0)
				}
			}

			maxPages := 100
			if cliutil.IsDogfoodEnv() {
				maxPages = 1
			}
			for _, resource := range resources {
				res := syncResource(cmd.Context(), c, s, resource, "", full, maxPages, false, false, nil, syncEventWriter)
				if res.Err != nil {
					fmt.Fprintf(cmd.ErrOrStderr(), "  %s: error: %v\n", resource, res.Err)
					continue
				}
				if res.Warn != nil {
					fmt.Fprintf(cmd.ErrOrStderr(), "  %s: warning: %v\n", resource, res.Warn)
					continue
				}
				totalSynced += res.Count
				fmt.Fprintf(cmd.ErrOrStderr(), "  %s: %d synced\n", resource, res.Count)
			}

			if flags.asJSON {
				enc := json.NewEncoder(cmd.OutOrStdout())
				enc.SetIndent("", "  ")
				return enc.Encode(map[string]any{
					"resources_synced": resourceCount,
					"total_items":      totalSynced,
					"store_path":       dbPath,
					"timestamp":        time.Now().UTC().Format(time.RFC3339),
				})
			}

			fmt.Fprintf(cmd.OutOrStdout(), "Archived %d items across %d resources to %s\n", totalSynced, resourceCount, dbPath)
			return nil
		},
	}

	cmd.Flags().StringVar(&dbPath, "db", "", "SQLite database file path (default: resolved data directory data.db)")
	cmd.Flags().BoolVar(&full, "full", false, "Full re-archive (ignore previous sync state)")

	return cmd
}

func newWorkflowStatusCmd(flags *rootFlags) *cobra.Command {
	var dbPath string

	cmd := &cobra.Command{
		Use:         "status",
		Short:       "Show local archive status and sync state for all resources",
		Annotations: map[string]string{"mcp:read-only": "true"},
		Example: `  # Show archive status
  judgeme-pp-cli workflow status

  # Show status as JSON
  judgeme-pp-cli workflow status --json`,
		RunE: func(cmd *cobra.Command, args []string) error {
			if dbPath == "" {
				dbPath = defaultDBPath("judgeme-pp-cli")
			}
			s, err := store.OpenWithContext(cmd.Context(), dbPath)
			if err != nil {
				return fmt.Errorf("opening store: %w", err)
			}
			defer s.Close()

			status, err := s.Status()
			if err != nil {
				return err
			}

			if flags.asJSON {
				enc := json.NewEncoder(cmd.OutOrStdout())
				enc.SetIndent("", "  ")
				return enc.Encode(status)
			}

			if len(status) == 0 {
				fmt.Fprintln(cmd.OutOrStdout(), "No archived data. Run 'workflow archive' to sync.")
				return nil
			}

			fmt.Fprintln(cmd.OutOrStdout(), "Archive Status:")
			total := 0
			for resource, count := range status {
				fmt.Fprintf(cmd.OutOrStdout(), "  %-30s %d items\n", resource, count)
				total += count
			}
			fmt.Fprintf(cmd.OutOrStdout(), "\n  Total: %d items\n", total)
			fmt.Fprintf(cmd.OutOrStdout(), "  Store: %s\n", dbPath)
			return nil
		},
	}

	cmd.Flags().StringVar(&dbPath, "db", "", "SQLite database file path (default: resolved data directory data.db)")

	return cmd
}

